/**
 * site origin of the site-local frame (FR-004-02)
 */
export interface SiteOrigin {
/**
 * EPSG code of the UTM zone of the site (NAD83(2011), ETRS89, NAD83, WGS 84 zones)
 */
epsg: number
easting_m: number
northing_m: number
/**
 * origin elevation z0 in the vertical datum of the inputs, m
 */
z0_m: number
}
/**
 * one DEM or LAZ file and the CRS read from it (FR-004-01)
 * 
 * This interface was referenced by `SceneManifest`'s JSON-Schema
 * via the `definition` "input".
 */
export interface Input {
source: Slug
file: Relpath
kind: ("dem" | "laz")
sha256: Sha256
crs: CrsRecord
}
/**
 * CRS and axis units read from the input's own metadata (FR-004-01, FR-004-03)
 */
export interface CrsRecord {
horizontal: CrsRef
vertical: CrsRef
horizontal_unit: LinearUnit
vertical_unit: LinearUnit
}
/**
 * terrain outputs and the holes left as nodata (FR-004-05, FR-004-12)
 * 
 * This interface was referenced by `SceneManifest`'s JSON-Schema
 * via the `definition` "terrain".
 */
export interface Terrain {
grid: FileRef
tiles: FileRef
cell_size_m: number
unfilled_holes: number
unfilled_cells: number
nodata_frac: number
}
/**
 * This interface was referenced by `SceneManifest`'s JSON-Schema
 * via the `definition` "file_ref".
 */
export interface FileRef {
path: Relpath
sha256: Sha256
}
/**
 * This interface was referenced by `SceneManifest`'s JSON-Schema
 * via the `definition` "design".
 */
export interface Design {
report: FileRef
road_network: FileRef
provenance: "design-code"
}
